var t=`0510-jachnun`;var o=`world-0510`;var r=`IL`;var a=`western-asia`;var i=8;var l=521;var s={en:`Jachnun`,ua:`Джахнун`};var u={en:`A traditional dish from Israel, centered on all-purpose flour. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ізраїль. Основні складники: пшеничне борошно універсальне. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,460,`g`],[`water`,230,`ml`],[`table-salt`,7,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[[`unsalted-butter`,180,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:12,i:[]},{en:`Bake the tightly rolled, buttered jachnun at about 100–110°C, well covered, overnight for 8 hours until deep amber.`,ua:`Випікайте щільно скручені й змащені маслом джахнуни під кришкою при 100–110°C всю ніч, близько 8 годин, до темно-бурштинового кольору.`,t:[`low-and-slow-cooking`],m:480,i:[]}];var g={slug:t,id:o,country:`IL`,region:a,servings:8,minutes:521,title:s,text:u,steps:d};export{r as country,g as default,o as id,l as minutes,a as region,i as servings,t as slug,d as steps,u as text,s as title};